/* DevFlow — progressively enhanced workspace UI; all mutations use the authenticated API. */
const $=s=>document.querySelector(s);const $$=s=>Array.from(document.querySelectorAll(s));
const state={boot:null,data:null,wid:null,view:'overview',pid:0,q:'',status:'all',priority:'all',assignee:'all',theme:document.documentElement.dataset.theme||'light',socket:null,openedTask:null};
const STATUS={backlog:['Backlog','#9995ab','◌'],todo:['A fazer','#aeb0bc','○'],in_progress:['Em andamento','#9b77ed','◕'],review:['Em revisão','#f0ae69','◉'],done:['Concluído','#4bc4a4','✓']};
const PRIORITY={none:['Sem prioridade','#aaa5b3','—'],low:['Baixa','#4fc5a0','↓'],medium:['Média','#f0ae69','•'],high:['Alta','#f08091','↑'],urgent:['Urgente','#e35473','‼']};
const ROLE={owner:'Proprietário',admin:'Admin',member:'Membro',viewer:'Visualizador'};
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;const fmtDate=s=>{if(!s)return 'Sem prazo';try{return new Date(s+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});}catch{return s}};
const ago=s=>{let diff=Math.max(0,Date.now()-new Date(s).getTime())/60000;return diff<1?'agora':diff<60?`${Math.floor(diff)} min atrás`:diff<1440?`${Math.floor(diff/60)} h atrás`:`${Math.floor(diff/1440)} d atrás`};
const initials=s=>String(s||'?').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const user=id=>state.data?.members.find(x=>x.id===id);const proj=id=>state.data?.projects.find(x=>x.id===id);
const key=t=>`${proj(t.project_id)?.key||'TASK'}-${t.number}`;const writable=()=>['owner','admin','member'].includes(state.data?.workspace.role);const admin=()=>['owner','admin'].includes(state.data?.workspace.role);const owner=()=>state.data?.workspace.role==='owner';
function toast(msg,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;$('#toast-host').appendChild(el);setTimeout(()=>el.remove(),3700)}
async function request(path,options={}){let method=options.method||'GET';let headers={'Accept':'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(method!=='GET'?{'X-CSRF-Token':state.boot?.csrf||''}:{})};let r=await fetch(path,{credentials:'same-origin',...options,headers:{...headers,...(options.headers||{})}});let data=await r.json().catch(()=>({detail:'Falha ao ler resposta do servidor.'}));if(!r.ok){if(r.status===401){location.href='/entrar';throw Error('Sessão expirada.')}throw Error(typeof data.detail==='string'?data.detail:'Não foi possível concluir a operação.');}return data;}
async function mutate(path,method,body){try{return await request(path,{method,body:JSON.stringify(body)})}catch(err){toast(err.message,'error');throw err}}
function prefix(){return `/api/workspaces/${state.wid}`}
async function loadData(){state.data=await request(`${prefix()}/data`);renderShell();render();}
function setupSocket(){try{state.socket?.close();const scheme=location.protocol==='https:'?'wss':'ws';state.socket=new WebSocket(`${scheme}://${location.host}/ws/${state.wid}`);state.socket.onmessage=ev=>{const data=JSON.parse(ev.data);if(data.actor!==state.boot?.user.id){loadData().catch(console.warn);if(state.openedTask===data.id)openTask(state.openedTask);}};}catch(err){console.warn('Sem canal em tempo real',err)}}
async function start(){try{state.boot=await request('/api/bootstrap');const token=sessionStorage.getItem('devflow-invitation');if(token){try{const r=await mutate(`/api/invites/${encodeURIComponent(token)}/accept`,'POST',{});state.wid=r.workspace_id;sessionStorage.removeItem('devflow-invitation');state.boot=await request('/api/bootstrap');toast('Convite aceito!');}catch{sessionStorage.removeItem('devflow-invitation')}}state.wid=state.wid||+(localStorage.getItem('devflow-workspace')||0);if(!state.boot.workspaces.some(w=>w.id===state.wid))state.wid=state.boot.workspaces[0]?.id;if(!state.wid)throw Error('Você ainda não participa de um workspace.');$('#loading').hidden=true;$('#shell').hidden=false;await loadData();setupSocket();}catch(ex){$('#loading').innerHTML=`<div class="startup-symbol">✦</div><strong>Não foi possível carregar seu workspace.</strong><p>${e(ex.message)}</p><a class="button solid" href="/entrar">Entrar novamente</a>`;}}
function renderShell(){let w=state.data.workspace,u=state.boot.user;$('#workspace-name').textContent=w.name;$('#workspace-avatar').textContent=initials(w.name).slice(0,1);$('#account-name').textContent=u.name;$('#account-mail').textContent=u.email;$('#account-avatar').textContent=initials(u.name);$('#top-avatar').textContent=initials(u.name);$('#account-avatar').style.backgroundColor=u.color;$('#top-avatar').style.backgroundColor=u.color;$('#theme-btn').textContent=state.theme==='dark'?'☀':'☾';const unreads=state.data.notifications.filter(x=>!x.read).length;$('#notif-badge').hidden=!unreads;$('#workspace-popup').innerHTML=state.boot.workspaces.map(x=>`<button data-switch-workspace="${x.id}">${e(x.name)} <small>${e(ROLE[x.role])}</small></button>`).join('');$('#project-links').innerHTML=state.data.projects.filter(p=>!p.archived).map(p=>`<button class="project-link ${state.view==='board'&&state.pid===p.id?'active':''}" data-project-id="${p.id}"><span class="project-symbol" style="background:${e(p.color)}">${e(p.icon)}</span><span>${e(p.name)}</span><small>${state.data.tasks.filter(t=>t.project_id===p.id).length}</small></button>`).join('')||'<p style="padding-left:14px;color:var(--muted);font-size:11px">Nenhum projeto ainda.</p>';$$('.side-link').forEach(x=>x.classList.toggle('active',x.dataset.view===state.view));$('#breadcrumb-current').textContent=state.view==='overview'?'Visão geral':state.view==='board'?'Quadro Kanban':state.view==='list'?'Minhas tarefas':state.view==='timeline'?'Cronograma':state.view==='insights'?'Relatórios':state.view==='activity'?'Atividades':state.view==='team'?'Equipe':'Configurações';}

async function reloadAccount(){
 const boot=await request('/api/bootstrap');
 state.boot=boot;
 await loadData();
}
function showProfile(){
 $('#account-dropdown').hidden=true;
 $('#account-btn').setAttribute('aria-expanded','false');
 navigation('settings');
 const section=$('#settings-profile-section');
 if(section)section.scrollIntoView({behavior:'smooth',block:'start'});
}
function navigation(view,pid=state.pid){$('#account-dropdown').hidden=true;$('#account-btn').setAttribute('aria-expanded','false');state.view=view;state.pid=pid;$('#sidebar').classList.remove('mobile-open');$('#mobile-shade').hidden=true;renderShell();render();}
function heading(kicker,title,subtitle,extra=''){return `<div class="page-heading"><div><div class="overline">${e(kicker)}</div><h1>${e(title)}</h1><p class="subtitle">${e(subtitle)}</p></div><div class="page-actions">${extra}</div></div>`}
function avatar(id){const u=user(id);return u?`<span class="assignee-bubble" style="background:${e(u.color)}" title="${e(u.name)}">${e(initials(u.name))}</span>`:'<span class="assignee-bubble empty" title="Sem responsável">+</span>'}
function statusPill(st){const [title]=STATUS[st]||STATUS.todo;return `<span class="status-pill ${st}"><span class="status-dot"></span>${e(title)}</span>`}
function priorityPill(p){return `<span class="priority-pill ${p}">${e(PRIORITY[p]?.[2]||'')} ${e(PRIORITY[p]?.[0]||p)}</span>`}
function filteredTasks(onlyMine=false){let ts=state.data.tasks.filter(t=>(!state.pid||t.project_id===state.pid)&&(!onlyMine||t.assignee_id===state.boot.user.id));if(state.q)ts=ts.filter(t=>(`${t.title} ${t.description} ${key(t)}`).toLowerCase().includes(state.q.toLowerCase()));if(state.status!=='all')ts=ts.filter(t=>t.status===state.status);if(state.priority!=='all')ts=ts.filter(t=>t.priority===state.priority);if(state.assignee!=='all')ts=ts.filter(t=>String(t.assignee_id||'none')===state.assignee);return ts}
function stats(){const ts=state.data.tasks;const today=new Date().toISOString().slice(0,10);return {total:ts.length,done:ts.filter(t=>t.status==='done').length,progress:ts.filter(t=>t.status==='in_progress').length,overdue:ts.filter(t=>t.due_date&&t.due_date<today&&t.status!=='done').length,review:ts.filter(t=>t.status==='review').length};}
function statCard(label,num,icon,color,note){return `<article class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-icon ${color}">${icon}</span></div><div class="stat-num">${num}</div><div class="stat-foot">${note}</div></article>`}
function recentTable(tasks,max=7){if(!tasks.length)return `<div class="empty-state"><span class="empty-icon">◈</span><h3>Tudo pronto para começar</h3><p>Crie sua primeira tarefa e organize o fluxo.</p><button class="button solid" data-action="create-task">+ Nova tarefa</button></div>`;return `<div class="table-scroll"><table class="task-table"><thead><tr><th>TAREFA</th><th>STATUS</th><th>PRIORIDADE</th><th>PRAZO</th><th>RESP.</th></tr></thead><tbody>${tasks.slice(0,max).map(t=>`<tr data-open-task="${t.id}"><td class="title-col"><span class="task-id">${e(key(t))}</span><span class="task-title-text">${e(t.title)}</span></td><td>${statusPill(t.status)}</td><td>${priorityPill(t.priority)}</td><td>${e(fmtDate(t.due_date))}</td><td>${avatar(t.assignee_id)}</td></tr>`).join('')}</tbody></table></div>`}
function activityIcon(verb){return ({created_task:'+',moved_task:'↗',updated_task:'✎',commented:'◌',created_project:'◈',invited_member:'♧',joined_workspace:'✦'})[verb]||'✧'}
function activityText(verb){return ({created_task:'criou uma tarefa',moved_task:'moveu uma tarefa',updated_task:'atualizou uma tarefa',commented:'comentou em uma tarefa',created_project:'criou um projeto',invited_member:'convidou para equipe',joined_workspace:'entrou no workspace',created_workspace:'criou um workspace',updated_project:'editou um projeto',updated_workspace:'alterou configurações'})[verb]||'fez uma atualização'}
function activityList(list,max=8){return `<div class="activity-stream">${list.slice(0,max).map(a=>`<div class="activity-item"><div class="activity-line-ico">${activityIcon(a.verb)}</div><div><strong>${e(user(a.actor_id)?.name||'Equipe')} ${activityText(a.verb)}</strong><p>${e(a.detail)}</p><time>${ago(a.created_at)}</time></div></div>`).join('')||'<p class="panel-sub">Ainda não há atividades por aqui.</p>'}</div>`}
function overview(){let ss=stats(),pct=ss.total?Math.round(ss.done/ss.total*100):0;const projects=state.data.projects.filter(p=>!p.archived);const first=state.boot.user.name.split(' ')[0];return `${heading('SEU ESPAÇO DE TRABALHO',`Bem-vindo de volta, ${first}.`,'Veja o que está acontecendo na sua equipe hoje.',`${writable()?'<button class="button ghost" data-action="create-project">+ Novo projeto</button><button class="button solid" data-action="create-task">+ Nova tarefa <span>↗</span></button>':''}`)}<div class="stats-grid">${statCard('Total de tarefas',ss.total,'▦','','Em todos os projetos')}${statCard('Em andamento',ss.progress,'◷','blue','Progresso ativo')}${statCard('Concluídas',ss.done,'✓','green','Entregas realizadas')}${statCard('Atrasadas',ss.overdue,'!','orange','Precisam de atenção')}</div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Visão do progresso</h2><p class="panel-sub">Acompanhe a evolução das entregas.</p></div><button class="text-link" data-action="nav-insights">Ver relatório ↗</button></div><div class="progress-figure"><div class="progress-donut" style="--pct:${pct}"><div class="donut-inner"><strong>${pct}%</strong><small>concluído</small></div></div><div class="progress-lines">${[['Concluídas',ss.done,'var(--green)'],['Em andamento',ss.progress,'var(--purple)'],['Em revisão',ss.review,'var(--orange)']].map(([l,n,c])=>`<div class="progress-line"><div><span>${l}</span><b>${n}</b></div><div class="progress-track"><i style="width:${ss.total?n/ss.total*100:0}%;background:${c}"></i></div></div>`).join('')}</div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Seus projetos</h2><p class="panel-sub">Tudo o que está em movimento.</p></div><button class="text-link" data-action="create-project">+ Adicionar</button></div>${projects.slice(0,4).map(p=>{const all=state.data.tasks.filter(t=>t.project_id===p.id),done=all.filter(t=>t.status==='done').length,progress=all.length?done/all.length*100:0;return `<button class="project-overview-card" data-project-id="${p.id}" style="width:100%;display:flex;align-items:center;gap:12px;padding:12px 7px;background:transparent;color:var(--ink);border:0;text-align:left;cursor:pointer"><span class="project-symbol" style="background:${e(p.color)};width:35px;height:35px">◈</span><span style="flex:1"><strong style="font-size:12px">${e(p.name)}</strong><small style="display:block;margin-top:5px;font-size:10px;color:var(--muted)">${all.length} tarefas · ${done} concluídas</small><span class="progress-track" style="display:block;margin-top:8px"><i style="width:${progress}%;background:${e(p.color)}"></i></span></span><span style="font-size:11px;color:var(--muted)">${Math.round(progress)}%</span></button>`}).join('')||'<div class="quick-add"><button data-action="create-project">+ Criar seu primeiro projeto</button></div>'}</section></div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Tarefas recentes</h2><p class="panel-sub">As tarefas mais relevantes do seu workspace.</p></div><button class="text-link" data-action="nav-list">Ver todas ↗</button></div>${recentTable(state.data.tasks.slice().sort((a,b)=>b.id-a.id),6)}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Atividade da equipe</h2><p class="panel-sub">Novidades do seu workspace.</p></div><button class="text-link" data-action="nav-activity">Ver tudo ↗</button></div>${activityList(state.data.activities,5)}</section></div>`}
function projectTabs(){return `<div class="project-chips"><button class="chip ${!state.pid?'active':''}" data-filter-project="0">Todos os projetos</button>${state.data.projects.filter(p=>!p.archived).map(p=>`<button class="chip ${state.pid===p.id?'active':''}" data-filter-project="${p.id}"><span style="color:${e(p.color)}">◈</span> ${e(p.name)}</button>`).join('')}</div>`}
function boardFilters(){return `<div class="board-toolbar"><div class="board-filters"><input class="filter-input" id="filter-search" type="search" placeholder="⌕ Buscar tarefas..." value="${e(state.q)}" aria-label="Buscar tarefas"><select class="filter-select" id="filter-priority"><option value="all">Prioridades</option>${Object.entries(PRIORITY).map(([k,v])=>`<option value="${k}" ${state.priority===k?'selected':''}>${e(v[0])}</option>`).join('')}</select><select class="filter-select" id="filter-assignee"><option value="all">Responsáveis</option><option value="none" ${state.assignee==='none'?'selected':''}>Não atribuídas</option>${state.data.members.map(x=>`<option value="${x.id}" ${state.assignee===String(x.id)?'selected':''}>${e(x.name)}</option>`).join('')}</select></div>${writable()?'<button class="button solid" data-action="create-task">+ Nova tarefa <span>↗</span></button>':''}</div>`}
function ticket(t){let overdue=t.due_date&&t.due_date<new Date().toISOString().slice(0,10)&&t.status!=='done';return `<article class="ticket" draggable="${writable()?'true':'false'}" data-open-task="${t.id}" data-ticket-id="${t.id}"><div class="ticket-id"><span class="ticket-priority" style="background:${e(PRIORITY[t.priority]?.[1]||'#999')}"></span>${e(key(t))}</div><div class="ticket-title">${e(t.title)}</div><div class="ticket-labels">${t.labels.slice(0,3).map(l=>`<span class="ticket-label" style="--tag-color:${e(l.color)}">${e(l.name)}</span>`).join('')}</div><div class="ticket-bottom"><div class="ticket-meta">${t.due_date?`<span class="${overdue?'overdue':''}">◷ ${e(fmtDate(t.due_date))}</span>`:''}${t.comment_count?`<span>☷ ${t.comment_count}</span>`:''}${t.check_count?`<span>☑ ${t.check_done}/${t.check_count}</span>`:''}</div>${avatar(t.assignee_id)}</div></article>`}
function board(){const p=proj(state.pid);return `${heading('GESTÃO DE PROJETOS',p?p.name:'Quadro Kanban','Um fluxo visual para manter o trabalho no ritmo.',`${p&&state.data.integrations?.[String(p.id)]?'<button class="button ghost" data-action="github-issues">◇ Issues GitHub</button>':''}${admin()&&p?'<button class="button ghost" data-action="edit-project">⚙ Projeto</button>':''}`)}${projectTabs()}${boardFilters()}<div class="board-scroll"><div class="board">${Object.entries(STATUS).map(([st,[label,color,symbol]])=>{let tasks=filteredTasks().filter(t=>t.status===st);return `<section class="kanban-column" data-drop-status="${st}"><div class="column-head"><div class="column-name"><i style="background:${color}"></i>${e(label)} <span class="column-count">${tasks.length}</span></div>${writable()?`<button class="column-add" data-action="create-task" data-status="${st}" title="Adicionar tarefa">+</button>`:''}</div>${tasks.map(ticket).join('')}${writable()?`<button class="new-in-column" data-action="create-task" data-status="${st}">+ Nova tarefa</button>`:''}</section>`}).join('')}</div></div>`}
function list(){const mine=filteredTasks(true);return `${heading('SEU TRABALHO','Minhas tarefas','Tudo o que foi atribuído a você, sem distrações.',writable()?'<button class="button solid" data-action="create-task">+ Nova tarefa</button>':'')}${projectTabs()}${boardFilters()}<section class="panel">${recentTable(mine.sort((a,b)=>(a.due_date||'9999').localeCompare(b.due_date||'9999')),999)}</section>`}
function timeline(){const tasks=filteredTasks().filter(t=>t.due_date).sort((a,b)=>a.due_date.localeCompare(b.due_date));const today=new Date().toISOString().slice(0,10);const groups=Object.groupBy?Object.groupBy(tasks,t=>t.due_date):tasks.reduce((a,t)=>((a[t.due_date]??=[]).push(t),a),{});return `${heading('PRAZOS E ENTREGAS','Cronograma da equipe','Veja o que precisa ser concluído nos próximos dias.',writable()?'<button class="button solid" data-action="create-task">+ Nova tarefa</button>':'')}${projectTabs()}${boardFilters()}<section class="panel" style="max-width:1050px"><div class="panel-head"><div><h2 class="panel-title">Próximas entregas</h2><p class="panel-sub">Tarefas organizadas por data de vencimento.</p></div><span class="status-pill">${tasks.length} tarefas com prazo</span></div>${Object.entries(groups).map(([date,items])=>`<div style="padding:14px 0;border-top:1px solid var(--line)"><div style="display:flex;align-items:center;gap:10px;margin-bottom:14px"><strong style="font-size:12px;color:${date<today?'var(--red)':'var(--purple)'}">${e(new Date(date+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'long',day:'2-digit',month:'long'}))}</strong><span style="font-size:10px;color:var(--muted)">${items.length} tarefa(s)</span></div>${items.map(t=>`<button data-open-task="${t.id}" style="width:100%;background:var(--surface-2);color:var(--ink);border:0;text-align:left;border-radius:9px;padding:12px 15px;display:flex;align-items:center;gap:14px;margin-bottom:7px;flex-wrap:wrap"><span style="font-size:11px;color:var(--muted)">${e(key(t))}</span><strong style="font-size:12px;flex:1">${e(t.title)}</strong>${statusPill(t.status)}${avatar(t.assignee_id)}</button>`).join('')}</div>`).join('')||'<div class="empty-state">Nenhuma tarefa com prazo definido.</div>'}</section>`}
function insights(){const all=state.data.tasks,ss=stats();const byProject=state.data.projects.filter(x=>!x.archived).map(p=>{let t=all.filter(t=>t.project_id===p.id);return {p,total:t.length,done:t.filter(x=>x.status==='done').length}});let max=Math.max(1,...byProject.map(x=>x.total));return `${heading('INTELIGÊNCIA DE PROJETOS','Visão dos resultados','Encontre gargalos e acompanhe a evolução da equipe.','<a class="button ghost" href="'+prefix()+'/export.csv">↓ Exportar CSV</a>')}<div class="stats-grid">${statCard('Tarefas criadas',ss.total,'▦','','Ao longo dos projetos')}${statCard('Concluídas',ss.done,'✓','green','Finalizadas')}${statCard('Em revisão',ss.review,'◉','orange','Aguardando validação')}${statCard('Fora do prazo',ss.overdue,'!','blue','Acompanhe esses itens')}</div><div class="insights-row"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Distribuição por projeto</h2><p class="panel-sub">Volume total de tarefas em cada iniciativa.</p></div></div><div class="chart-bars">${byProject.map(x=>`<div class="bar-wrap"><strong style="color:var(--muted);font-size:10px">${x.total}</strong><i style="height:${Math.max(3,x.total/max*135)}px;background:linear-gradient(180deg,${e(x.p.color)},var(--purple))"></i><small>${e(x.p.key)}</small></div>`).join('')}</div><div class="charts-legend"><span><i class="legend-dot" style="background:var(--purple)"></i>Total por projeto</span></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Resumo de execução</h2><p class="panel-sub">Distribuição das tarefas por status.</p></div></div>${Object.entries(STATUS).map(([k,v])=>{const n=all.filter(x=>x.status===k).length;return `<div class="stat-subcard"><span><span style="color:${v[1]}">●</span> ${e(v[0])}</span><b>${n}</b></div>`}).join('')}</section></div><section class="panel" style="margin-top:20px"><div class="panel-head"><div><h2 class="panel-title">Desempenho dos projetos</h2><p class="panel-sub">Percentual de tarefas concluídas por projeto.</p></div></div>${byProject.map(x=>`<div class="progress-line" style="margin:20px 0"><div><span>${e(x.p.name)}</span><b>${x.total?Math.round(x.done/x.total*100):0}% · ${x.done}/${x.total}</b></div><div class="progress-track"><i style="width:${x.total?x.done/x.total*100:0}%;background:${e(x.p.color)}"></i></div></div>`).join('')}</section>`}
function activities(){return `${heading('HISTÓRICO DO WORKSPACE','Tudo o que aconteceu','Acompanhe cada movimento importante da sua equipe.')}<section class="panel" style="max-width:860px">${activityList(state.data.activities,80)}</section>`}
function team(){return `${heading('PESSOAS E COLABORAÇÃO','Seu time, um só ritmo','Gerencie as pessoas que participam do workspace.',admin()?'<button class="button solid" data-action="invite">+ Convidar pessoa <span>↗</span></button>':'')}<div class="section-row"><h2>${state.data.members.length} integrante(s)</h2><span style="color:var(--muted);font-size:12px">Workspace: ${e(state.data.workspace.name)}</span></div><div class="member-cards">${state.data.members.map(m=>`<article class="member-card">${avatar(m.id)}<div style="flex:1;min-width:0"><strong>${e(m.name)}</strong><small>${e(m.email)}</small></div><span class="role-badge">${e(ROLE[m.role])}</span></article>`).join('')}</div><section class="panel" style="margin-top:24px;max-width:780px"><h2 class="panel-title">Permissões de acesso</h2><p class="panel-sub" style="line-height:1.9;margin-top:12px">Proprietários gerenciam todo o workspace. Administradores podem convidar pessoas e configurar projetos. Membros criam tarefas e colaboram. Visualizadores acompanham os projetos sem alterar os dados.</p></section>`}

function settings(){
 const w=state.data.workspace,u=state.boot.user;
 const colors=['#8b5cf6','#3b82f6','#0f9e8b','#f59e0b','#ef6c88','#64748b'];
 const swatches=colors.map((color,i)=>`<label title="Cor ${i+1}"><input type="radio" name="avatar_color" value="${color}" ${u.color.toLowerCase()===color?'checked':''} required><span style="--swatch:${color}" aria-hidden="true">${u.color.toLowerCase()===color?'✓':''}</span></label>`).join('');
 const selected=colors.some(c=>c===u.color.toLowerCase());
 return `${heading('CONTA E PREFERÊNCIAS','Configurações','Sua identidade, segurança e configurações da equipe em um só lugar.')}
 <section class="panel settings-section" id="settings-profile-section">
 <div class="settings-section-head"><span class="settings-icon">◉</span><div><h2>Meu perfil</h2><p>Atualize suas informações pessoais. Elas aparecem para sua equipe nas tarefas e atividades.</p></div></div>
 <div class="settings-row"><div><h3>Dados pessoais</h3><p>Seu nome, e-mail e avatar são exclusivos da sua conta, mesmo em vários workspaces.</p></div>
 <form class="settings-form" id="profile-form" autocomplete="on">
 <div><label for="settings-user-name">Nome completo</label><input id="settings-user-name" name="name" value="${e(u.name)}" minlength="2" maxlength="120" autocomplete="name" required></div>
 <div><label for="settings-user-mail">E-mail de acesso</label><input id="settings-user-mail" name="email" type="email" value="${e(u.email)}" autocomplete="email" required></div>
 <div><label>Cor do avatar</label><div class="settings-swatches" role="group" aria-label="Cor do avatar">${selected?swatches:`<label title="Cor atual"><input name="avatar_color" type="radio" value="${e(u.color)}" checked><span style="--swatch:${e(u.color)}" aria-hidden="true">✓</span></label>`+swatches}</div></div>
 <div><label for="settings-profile-password">Confirme sua senha atual</label><input id="settings-profile-password" name="current_password" type="password" minlength="1" autocomplete="current-password" placeholder="Obrigatória para salvar o perfil" required></div>
 <p class="settings-form-hint">O e-mail é usado para entrar na conta. A nova cor também aparece no quadro e nas informações da equipe.</p>
 <button class="button solid settings-submit" type="submit">Salvar meu perfil ↗</button>
 </form></div></section>
 <section class="panel settings-section" id="settings-security-section"><div class="settings-section-head"><span class="settings-icon">◇</span><div><h2>Senha e segurança</h2><p>Altere sua senha com segurança. Esta ação não modifica os dados dos projetos.</p></div></div>
 <div class="settings-row"><div><h3>Alterar senha</h3><p>Use uma senha exclusiva e guarde-a em um gerenciador de senhas.</p></div>
 <form class="settings-form" id="password-form">
 <div><label for="change-current-password">Senha atual</label><input id="change-current-password" name="current_password" type="password" autocomplete="current-password" required></div>
 <div><label for="change-new-password">Nova senha</label><input id="change-new-password" name="new_password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required></div>
 <div><label for="change-confirm-password">Confirme a nova senha</label><input id="change-confirm-password" name="confirm_password" type="password" minlength="10" maxlength="128" autocomplete="new-password" required></div>
 <p class="settings-password-hint">Pelo menos 10 caracteres, incluindo letras e números. A senha deve ser diferente da atual.</p>
 <button class="button solid settings-submit" type="submit">Alterar minha senha ↗</button>
 </form></div></section>
 <section class="panel settings-section"><div class="settings-section-head"><span class="settings-icon">⚙</span><div><h2>Workspace e aparência</h2><p>Personalize o espaço de trabalho e o tema da sua interface.</p></div></div>
 <div class="settings-row"><div><h3>Identidade da equipe</h3><p>${admin()?'Administradores podem atualizar os dados deste workspace.':'Somente administradores podem alterar os dados do workspace.'}</p></div><form id="settings-form" class="settings-form"><div><label for="settings-workspace-name">Nome do workspace</label><input id="settings-workspace-name" name="name" value="${e(w.name)}" required minlength="2" maxlength="120" ${admin()?'':'disabled'}></div><div><label for="settings-workspace-description">Descrição</label><textarea id="settings-workspace-description" name="description" maxlength="2000" ${admin()?'':'disabled'}>${e(w.description)}</textarea></div>${admin()?'<button class="button solid settings-submit" type="submit">Salvar workspace ↗</button>':''}</form></div>
 <div class="settings-row"><div><h3>Aparência</h3><p>Esta preferência é salva neste navegador.</p></div><div><label>Modo de exibição</label><div class="project-chips"><button type="button" class="chip ${state.theme==='light'?'active':''}" data-set-theme="light">☀ Claro</button><button type="button" class="chip ${state.theme==='dark'?'active':''}" data-set-theme="dark">☾ Escuro</button></div></div></div>
 <div class="settings-row"><div><h3>Dados do workspace</h3><p>Exporte tarefas em CSV. A exportação respeita sua permissão de leitura.</p></div><div class="settings-access"><span class="settings-badge">${e(ROLE[w.role]||w.role)}</span><a class="button ghost" href="${prefix()}/export.csv">↓ Exportar tarefas CSV</a></div></div>
 </section>`;
}
function render(){if(!state.data)return;renderShell();let content={overview,list,board,timeline,insights,activity:activities,team,settings}[state.view]||overview;$('#view-root').innerHTML=content();}
function modal(html){$('#modal').innerHTML=html;$('#modal-backdrop').hidden=false;$('#modal').focus();document.body.style.overflow='hidden';}
function closeModal(){if($('#modal-backdrop').hidden)return;$('#modal-backdrop').hidden=true;$('#modal').innerHTML='';document.body.style.overflow='';}
function projectForm(edit=false){if(!writable())return;const p=edit?proj(state.pid):null;const title=edit?'Configurações do projeto':'Criar um projeto';modal(`<div class="modal-header"><div><h2>${title}</h2><p>${edit?'Atualize as informações deste projeto.':'Um novo espaço para organizar as entregas da equipe.'}</p></div><button class="close-btn" data-action="close-modal">✕</button></div><form id="project-form"><div class="form-group"><label>Nome do projeto</label><input name="name" required maxlength="120" minlength="2" value="${e(p?.name||'')}" placeholder="Ex.: Plataforma Aurora"></div><div class="form-row"><div class="form-group"><label>Identificador</label><input name="key" required minlength="2" maxlength="12" placeholder="AUR" value="${e(p?.key||'')}" ${edit?'disabled':''}></div><div class="form-group"><label>Cor de destaque</label><input name="color" type="color" value="${e(p?.color||'#865cf6')}" style="height:44px;padding:4px"></div></div><div class="form-group"><label>Descrição</label><textarea name="description" maxlength="2000" placeholder="Conte sobre o objetivo do projeto">${e(p?.description||'')}</textarea></div>${admin()?`<div class="form-group"><label>GitHub — repositório (opcional)</label><input name="github_repo" placeholder="usuario/repositorio" value="${e(state.data.integrations?.[String(p?.id)]||'')}"><p class="form-hint">Conecte um repositório para consultar e importar issues.</p></div>`:''}${edit?`<div class="form-group"><label><input type="checkbox" name="archived" style="width:auto;margin-right:8px" ${p.archived?'checked':''}> Arquivar projeto</label></div>`:''}<div class="modal-footer"><button type="button" class="button ghost" data-action="close-modal">Cancelar</button><button class="button solid">${edit?'Salvar projeto':'Criar projeto'}</button></div></form>`);$('#project-form').onsubmit=async ev=>{ev.preventDefault();let d=Object.fromEntries(new FormData(ev.currentTarget));d.color=d.color||'#865cf6';if(edit){delete d.key;d.archived=$('[name="archived"]').checked;}try{const repo=d.github_repo?.trim();delete d.github_repo;let r=await mutate(edit?`${prefix()}/projects/${p.id}`:`${prefix()}/projects`,edit?'PATCH':'POST',d);if(repo&&admin())await mutate(`${prefix()}/projects/${r.id}/github`,'PUT',{repository:repo});closeModal();if(!edit)state.pid=r.id;await loadData();toast(edit?'Projeto atualizado.':'Projeto criado.');if(!edit)navigation('board',r.id);}catch{}}}
function taskForm(status='todo'){if(!writable())return;const projects=state.data.projects.filter(p=>!p.archived),pid=state.pid||projects[0]?.id;if(!pid){toast('Crie um projeto antes.','error');projectForm();return}modal(`<div class="modal-header"><div><h2>Nova tarefa</h2><p>Transforme uma ideia em uma próxima ação.</p></div><button class="close-btn" data-action="close-modal">✕</button></div><form id="task-create-form"><div class="form-group"><label>Título da tarefa</label><input name="title" autofocus required maxlength="240" minlength="2" placeholder="O que precisa ser feito?"></div><div class="form-row"><div class="form-group"><label>Projeto</label><select name="project_id">${projects.map(p=>`<option value="${p.id}" ${p.id===pid?'selected':''}>${e(p.name)}</option>`).join('')}</select></div><div class="form-group"><label>Status</label><select name="status">${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${k===status?'selected':''}>${e(v[0])}</option>`).join('')}</select></div></div><div class="form-group"><label>Descrição</label><textarea name="description" placeholder="Detalhes, contexto e critérios de aceite..."></textarea></div><div class="form-row"><div class="form-group"><label>Prioridade</label><select name="priority">${Object.entries(PRIORITY).map(([k,v])=>`<option value="${k}" ${k==='medium'?'selected':''}>${e(v[0])}</option>`).join('')}</select></div><div class="form-group"><label>Responsável</label><select name="assignee_id"><option value="">Não atribuir</option>${state.data.members.map(x=>`<option value="${x.id}" ${x.id===state.boot.user.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></div></div><div class="form-row"><div class="form-group"><label>Prazo</label><input name="due_date" type="date"></div><div class="form-group"><label>Estimativa (pontos)</label><input name="estimate" min="0" max="1000" type="number" placeholder="Ex.: 3"></div></div><div class="modal-footer"><button class="button ghost" type="button" data-action="close-modal">Cancelar</button><button class="button solid">Criar tarefa <span>↗</span></button></div></form>`);$('#task-create-form').onsubmit=async ev=>{ev.preventDefault();const raw=Object.fromEntries(new FormData(ev.currentTarget));let d={...raw,project_id:+raw.project_id,assignee_id:raw.assignee_id?+raw.assignee_id:null,estimate:raw.estimate?+raw.estimate:null,due_date:raw.due_date||null};try{const created=await mutate(`${prefix()}/tasks`,'POST',d);closeModal();await loadData();toast('Tarefa criada.');openTask(created.id);}catch{}}}
async function showGithubIssues(){const p=proj(state.pid);if(!p)return;modal(`<div class="modal-header"><div><h2>Issues do GitHub</h2><p>${e(state.data.integrations?.[String(p.id)]||'')} · Importe tickets em segundos.</p></div><button class="close-btn" data-action="close-modal">✕</button></div><div id="github-issues-list"><p class="panel-sub">Consultando o GitHub...</p></div>`);try{const r=await request(`${prefix()}/projects/${p.id}/github/issues`);$('#github-issues-list').innerHTML=r.issues.map(x=>`<div style="padding:12px 0;border-top:1px solid var(--line);display:flex;align-items:center;gap:10px"><div style="flex:1;min-width:0"><strong style="font-size:12px">#${x.number} · ${e(x.title)}</strong><small style="display:block;margin-top:5px;color:var(--muted)"><a target="_blank" rel="noopener noreferrer" href="${e(x.url)}">Ver no GitHub ↗</a></small></div>${x.imported?'<span class="status-pill done">Importada</span>':writable()?`<button class="button ghost" data-import-github="${x.number}">Importar</button>`:''}</div>`).join('')||'<p class="panel-sub">Nenhuma issue aberta encontrada.</p>';$$('#github-issues-list [data-import-github]').forEach(b=>b.onclick=async()=>{try{await mutate(`${prefix()}/projects/${p.id}/github/issues/${b.dataset.importGithub}/import`,'POST',{});closeModal();await loadData();toast('Issue importada como tarefa.')}catch{}});}catch(ex){$('#github-issues-list').innerHTML=`<div class="form-error">${e(ex.message)}</div>`;}}
function inviteForm(){if(!admin())return;modal(`<div class="modal-header"><div><h2>Convidar para equipe</h2><p>Colaboração começa com as pessoas certas.</p></div><button class="close-btn" data-action="close-modal">✕</button></div><form id="invite-form"><div class="form-group"><label>E-mail da pessoa</label><input required name="email" type="email" placeholder="colega@empresa.com"></div><div class="form-group"><label>Nível de acesso</label><select name="role"><option value="member">Membro — pode editar tarefas</option><option value="admin">Admin — gerencia projetos e equipe</option><option value="viewer">Visualizador — somente leitura</option></select></div><p class="form-hint">O DevFlow gera um link que você poderá compartilhar. O envio por e-mail não é automático nesta versão.</p><div id="invite-result"></div><div class="modal-footer"><button class="button ghost" type="button" data-action="close-modal">Fechar</button><button class="button solid" type="submit">Gerar convite ↗</button></div></form>`);$('#invite-form').onsubmit=async ev=>{ev.preventDefault();let d=Object.fromEntries(new FormData(ev.currentTarget));try{const r=await mutate(`${prefix()}/invites`,'POST',d);$('#invite-result').innerHTML=`<label>Link de convite</label><input id="invite-link" readonly value="${e(r.link)}"><button class="button ghost" type="button" id="copy-invite" style="margin-top:9px">Copiar link</button>`;$('#copy-invite').onclick=async()=>{try{await navigator.clipboard.writeText(r.link);toast('Link copiado!')}catch{toast('Selecione e copie o link acima.')}};await loadData();}catch{}}}
async function openTask(id){state.openedTask=+id;let detail;try{detail=await request(`${prefix()}/tasks/${id}`)}catch(err){toast(err.message,'error');return}const t=detail.task,p=proj(t.project_id);$('#task-sheet-backdrop').hidden=false;$('#task-sheet').hidden=false;const labels=state.data.labels;$('#task-sheet').innerHTML=`<div class="sheet-top"><div class="sheet-id"><span style="color:${e(p?.color||'var(--purple)')}">◈</span> ${e(key(t))} <span style="color:var(--muted-2)">/ ${e(p?.name||'')}</span></div><button class="close-btn" data-action="close-task" aria-label="Fechar">✕</button></div><div class="sheet-heading">${e(t.title)}</div><form id="task-edit-form"><div class="form-group"><label>Título</label><input name="title" value="${e(t.title)}" required maxlength="240" ${writable()?'':'disabled'}></div><div class="sheet-info-grid"><div><label>Status</label><select name="status" ${writable()?'':'disabled'}>${Object.entries(STATUS).map(([k,v])=>`<option value="${k}" ${t.status===k?'selected':''}>${e(v[0])}</option>`).join('')}</select></div><div><label>Prioridade</label><select name="priority" ${writable()?'':'disabled'}>${Object.entries(PRIORITY).map(([k,v])=>`<option value="${k}" ${t.priority===k?'selected':''}>${e(v[0])}</option>`).join('')}</select></div><div><label>Responsável</label><select name="assignee_id" ${writable()?'':'disabled'}><option value="">Não atribuído</option>${state.data.members.map(x=>`<option value="${x.id}" ${t.assignee_id===x.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></div><div><label>Prazo</label><input name="due_date" type="date" value="${e(t.due_date||'')}" ${writable()?'':'disabled'}></div><div><label>Pontos de esforço</label><input name="estimate" type="number" min="0" max="1000" placeholder="Sem estimativa" value="${t.estimate??''}" ${writable()?'':'disabled'}></div><div><label>Última atualização</label><input value="${e(new Date(t.updated_at).toLocaleDateString('pt-BR'))}" disabled></div></div><div class="sheet-desc"><label>Descrição</label><textarea name="description" maxlength="8000" placeholder="Adicione detalhes e referências" ${writable()?'':'disabled'}>${e(t.description)}</textarea></div><div class="sheet-section"><div class="detail-section-title">Etiquetas</div><div class="label-picker">${labels.map(l=>`<button type="button" data-label-id="${l.id}" class="label-choice ${t.labels.some(x=>x.id===l.id)?'selected':''}" ${writable()?'':'disabled'}>${e(l.name)}</button>`).join('')}</div></div>${writable()?'<div style="display:flex;justify-content:flex-end;margin-top:25px"><button class="button solid">Salvar alterações ↗</button></div>':''}</form><div class="sheet-section"><div class="detail-section-title">Checklist <span style="color:var(--muted)">${detail.checklist.filter(x=>x.checked).length}/${detail.checklist.length}</span></div><div class="progress-track" style="margin-bottom:16px"><i style="background:var(--purple);width:${detail.checklist.length?detail.checklist.filter(x=>x.checked).length/detail.checklist.length*100:0}%"></i></div>${detail.checklist.map(c=>`<label class="check-row"><input type="checkbox" data-check-id="${c.id}" ${c.checked?'checked':''} ${writable()?'':'disabled'}><span class="${c.checked?'checked':''}">${e(c.text)}</span></label>`).join('')}${writable()?'<form id="add-check-form" class="check-input-row"><input name="text" maxlength="240" placeholder="Adicionar item à lista" required><button class="button ghost" type="submit">Adicionar</button></form>':''}</div><div class="sheet-section"><div class="detail-section-title">Comentários <span style="color:var(--muted)">${detail.comments.length}</span></div>${detail.comments.map(c=>`<div class="comment">${avatar(c.user_id)}<div class="comment-bubble"><strong>${e(user(c.user_id)?.name||'Membro')}</strong><small>${ago(c.created_at)}</small><p>${e(c.body)}</p></div></div>`).join('')||'<p class="panel-sub">Ainda não há comentários. Inicie a conversa!</p>'}${writable()?'<form id="comment-form" class="comment-form"><textarea name="body" required maxlength="5000" placeholder="Escreva um comentário..."></textarea><button class="button solid">Enviar ↗</button></form>':''}</div>`;
    $$('#task-sheet [data-label-id]').forEach(x=>x.onclick=()=>x.classList.toggle('selected'));
    const edit=$('#task-edit-form');if(edit)edit.onsubmit=async ev=>{ev.preventDefault();const raw=Object.fromEntries(new FormData(edit));const labelsSelected=$$('#task-sheet .label-choice.selected').map(x=>+x.dataset.labelId);let body={...raw,assignee_id:raw.assignee_id?+raw.assignee_id:null,estimate:raw.estimate?+raw.estimate:null,due_date:raw.due_date||null,label_ids:labelsSelected,version:t.version};try{await mutate(`${prefix()}/tasks/${id}`,'PATCH',body);await loadData();await openTask(id);toast('Tarefa atualizada.')}catch(err){if(err.message.includes('atualizada por outra pessoa')){await loadData();await openTask(id);}}};
    const cf=$('#comment-form');if(cf)cf.onsubmit=async ev=>{ev.preventDefault();let body=cf.elements.body.value;try{await mutate(`${prefix()}/tasks/${id}/comments`,'POST',{body});await loadData();await openTask(id);toast('Comentário enviado.')}catch{}};
    const ck=$('#add-check-form');if(ck)ck.onsubmit=async ev=>{ev.preventDefault();let text=ck.elements.text.value;try{await mutate(`${prefix()}/tasks/${id}/checklist`,'POST',{text});await loadData();await openTask(id);}catch{}};
    $$('#task-sheet [data-check-id]').forEach(el=>el.onchange=async()=>{try{await mutate(`${prefix()}/tasks/${id}/checklist/${el.dataset.checkId}`,'PATCH',{checked:el.checked});await loadData();await openTask(id);}catch{el.checked=!el.checked}});
}
function closeTask(){state.openedTask=null;$('#task-sheet').hidden=true;$('#task-sheet-backdrop').hidden=true;}
function showNotifications(){const existing=$('#notification-panel');if(existing){existing.remove();return}const n=document.createElement('div');n.id='notification-panel';n.className='notif-panel';n.innerHTML=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><strong>Notificações</strong><button class="close-btn" id="close-notif">✕</button></div>${state.data.notifications.slice(0,12).map(x=>`<button class="notif-item ${x.read?'':'unread'}" data-read-notif="${x.id}" data-open-task-if="${x.task_id||''}"><strong>${e(x.title)}</strong><small>${e(x.body)}</small></button>`).join('')||'<p class="panel-sub">Você está em dia. Nenhuma notificação por enquanto.</p>'}`;document.body.appendChild(n);$('#close-notif').onclick=()=>n.remove();n.addEventListener('click',async ev=>{const b=ev.target.closest('[data-read-notif]');if(!b)return;await mutate(`${prefix()}/notifications/${b.dataset.readNotif}`,'PATCH',{});n.remove();await loadData();if(b.dataset.openTaskIf)openTask(+b.dataset.openTaskIf)});}
function globalSearch(){modal(`<div class="modal-header"><div><h2>Buscar no workspace</h2><p>Encontre qualquer tarefa rapidamente.</p></div><button class="close-btn" data-action="close-modal">✕</button></div><input id="global-query" autofocus placeholder="Buscar título ou código..." aria-label="Busca global"><div id="global-results" style="max-height:360px;overflow-y:auto;margin-top:10px"></div>`);const render=()=>{let q=$('#global-query').value.toLowerCase();$('#global-results').innerHTML=state.data.tasks.filter(t=>(`${t.title} ${key(t)}`).toLowerCase().includes(q)).slice(0,20).map(t=>`<button class="search-result" data-global-task="${t.id}"><span>${e(t.title)}</span><small>${e(key(t))}</small></button>`).join('')||'<p class="panel-sub" style="padding:15px">Nenhuma tarefa encontrada.</p>';$('#global-results').querySelectorAll('[data-global-task]').forEach(b=>b.onclick=()=>{closeModal();openTask(+b.dataset.globalTask)})};$('#global-query').oninput=render;render();$('#global-query').focus()}
function setupHandlers(){document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(b){const action=b.dataset.action;if(action==='create-task')taskForm(b.dataset.status||'todo');if(action==='create-project')projectForm();if(action==='edit-project')projectForm(true);if(action==='invite')inviteForm();if(action==='github-issues')showGithubIssues();if(action==='close-modal')closeModal();if(action==='close-task')closeTask();if(action==='nav-insights')navigation('insights');if(action==='nav-list')navigation('list');if(action==='nav-activity')navigation('activity');}
    const projEl=ev.target.closest('[data-project-id]');if(projEl&&!ev.target.closest('.modal'))navigation('board',+projEl.dataset.projectId);
    const taskEl=ev.target.closest('[data-open-task]');if(taskEl)openTask(+taskEl.dataset.openTask);
    const tab=ev.target.closest('[data-filter-project]');if(tab){state.pid=+tab.dataset.filterProject;render();}
    const th=ev.target.closest('[data-set-theme]');if(th)setTheme(th.dataset.setTheme);
    const switcher=ev.target.closest('[data-switch-workspace]');if(switcher){state.wid=+switcher.dataset.switchWorkspace;localStorage.setItem('devflow-workspace',state.wid);state.pid=0;state.view='overview';$('#workspace-popup').hidden=true;loadData().then(setupSocket);}
});
$$('.side-link').forEach(b=>b.onclick=()=>navigation(b.dataset.view,b.dataset.view==='board'?0:state.pid));$('#add-project-side').onclick=()=>projectForm();$('#theme-btn').onclick=()=>setTheme(state.theme==='light'?'dark':'light');$('#workspace-select').onclick=()=>{$('#workspace-popup').hidden=!$('#workspace-popup').hidden};$('#account-btn').onclick=()=>{const dropdown=$('#account-dropdown');dropdown.hidden=!dropdown.hidden;$('#account-btn').setAttribute('aria-expanded',String(!dropdown.hidden));};$('#account-profile-btn').onclick=showProfile;$('#account-workspace-btn').onclick=()=>{$('#account-dropdown').hidden=true;$('#account-btn').setAttribute('aria-expanded','false');navigation('settings');};$('#logout-btn').onclick=async()=>{const btn=$('#logout-btn');btn.disabled=true;try{await mutate('/api/auth/logout','POST',{});state.socket?.close();localStorage.removeItem('devflow-workspace');location.replace('/entrar');}catch{btn.disabled=false;}};$('#notif-btn').onclick=showNotifications;$('#global-search').onclick=globalSearch;$('#open-sidebar').onclick=()=>{$('#sidebar').classList.add('mobile-open');$('#mobile-shade').hidden=false};$('#close-sidebar').onclick=closeSidebar;$('#mobile-shade').onclick=closeSidebar;$('#task-sheet-backdrop').onclick=closeTask;$('#modal-backdrop').addEventListener('click',ev=>{if(ev.target.id==='modal-backdrop')closeModal()});document.addEventListener('keydown',ev=>{if(ev.key==='Escape'){closeModal();closeTask();$('#notification-panel')?.remove();}if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();globalSearch()}});
    $('#view-root').addEventListener('input',ev=>{if(ev.target.id==='filter-search'){const start=ev.target.selectionStart;state.q=ev.target.value;const root=$('#view-root');if(state.view==='board'){const boardRoot=root.querySelector('.board');if(boardRoot){const existing=document.activeElement;existing.blur();render();const f=$('#filter-search');f.focus();f.setSelectionRange(start,start);}}else if(state.view==='list'||state.view==='timeline'){render();const f=$('#filter-search');f.focus();f.setSelectionRange(start,start);}}});
    $('#view-root').addEventListener('change',ev=>{if(ev.target.id==='filter-priority'){state.priority=ev.target.value;render()}if(ev.target.id==='filter-assignee'){state.assignee=ev.target.value;render()}});
    $('#view-root').addEventListener('submit',async ev=>{
    const form=ev.target;
    if(form.id==='profile-form'){
      ev.preventDefault();const data=Object.fromEntries(new FormData(form));
      const button=form.querySelector('[type=submit]');button.disabled=true;
      try{
        await mutate('/api/account/profile','PATCH',data);
        await reloadAccount();
        toast('Perfil salvo! Nome, e-mail e avatar atualizados.');
      }catch{}finally{button.disabled=false;}
    }
    if(form.id==='password-form'){
      ev.preventDefault();const data=Object.fromEntries(new FormData(form));
      if(data.new_password!==data.confirm_password){toast('As senhas não coincidem.','error');return;}
      delete data.confirm_password;
      const button=form.querySelector('[type=submit]');button.disabled=true;
      try{
        await mutate('/api/account/change-password','POST',data);
        form.reset();
        toast('Senha alterada com sucesso.');
      }catch{}finally{button.disabled=false;}
    }
    if(form.id==='settings-form'){
      ev.preventDefault();let d=Object.fromEntries(new FormData(form));
      const button=form.querySelector('[type=submit]');if(button)button.disabled=true;
      try{await mutate(prefix(),'PATCH',d);await loadData();toast('Configurações do workspace salvas.');}catch{}finally{if(button)button.disabled=false;}
    }
  });
    let dragTask=null;$('#view-root').addEventListener('dragstart',ev=>{const t=ev.target.closest('[data-ticket-id]');if(!t)return;dragTask=+t.dataset.ticketId;t.classList.add('dragging');if(ev.dataTransfer){ev.dataTransfer.effectAllowed='move';ev.dataTransfer.setData('text/plain',String(dragTask))}});$('#view-root').addEventListener('dragend',()=>{$$('.ticket.dragging').forEach(el=>el.classList.remove('dragging'));$$('.kanban-column.dragover').forEach(el=>el.classList.remove('dragover'));dragTask=null});$('#view-root').addEventListener('dragover',ev=>{const col=ev.target.closest('[data-drop-status]');if(col&&dragTask){ev.preventDefault();col.classList.add('dragover')}});$('#view-root').addEventListener('dragleave',ev=>{const col=ev.target.closest('[data-drop-status]');if(col&&!col.contains(ev.relatedTarget))col.classList.remove('dragover')});$('#view-root').addEventListener('drop',async ev=>{const col=ev.target.closest('[data-drop-status]');if(!col||!dragTask)return;ev.preventDefault();let t=state.data.tasks.find(x=>x.id===dragTask);col.classList.remove('dragover');if(!t||t.status===col.dataset.dropStatus)return;try{await mutate(`${prefix()}/tasks/${t.id}`,'PATCH',{status:col.dataset.dropStatus,version:t.version});await loadData();toast('Tarefa movida.')}catch{await loadData()}dragTask=null});
}
function closeSidebar(){$('#sidebar').classList.remove('mobile-open');$('#mobile-shade').hidden=true}
function setTheme(theme){state.theme=theme;document.documentElement.dataset.theme=theme;localStorage.setItem('devflow-theme',theme);renderShell();if(state.view==='settings')render()}
setupHandlers();start();
